def multi_future(children):
    """Waits for multiple `.Future` objects in parallel.

    Takes a list of `.Future` objects and returns a new `.Future` that
    resolves to a list of the results of each `.Future` (in the same order
    as the input list).  If a dict is passed instead of a list, the
    result is a dict with the same keys as the input.  If any of the
    inputs results in an exception, the returned `.Future` resolves
    with that exception.

    It is not necessary to call `multi_future` explicitly, since the
    engine will do so automatically when the generator yields a list of
    ``Futures``.

    .. versionadded:: 4.0
    """
    if isinstance(children, dict):
        keys = list(children.keys())
        children = children.values()
    else:
        keys = None
    children = list(map(maybe_future, children))
    assert all(is_future(i) for i in children)
    unfinished_children = set(children)

    future = TracebackFuture()
    if not children:
        future.set_result({} if keys is not None else [])

    def callback(f):
        unfinished_children.remove(f)
        if not unfinished_children:
            result_list = []
            try:
                for i in children:
                    result_list.append(i.result())
            except Exception:
                future.set_exc_info(sys.exc_info())
            else:
                if keys is not None:
                    future.set_result(dict(zip(keys, result_list)))
                else:
                    future.set_result(result_list)

    listening = set()
    for f in children:
        if f not in listening:
            listening.add(f)
            f.add_done_callback(callback)
    return future


